<?php
namespace App\Providers\Filament;
use App\Filament\Pages\Auth\Login; use App\Filament\Pages\ChangePassword;
use Filament\Http\Middleware\Authenticate; use Filament\Http\Middleware\AuthenticateSession; use Filament\Http\Middleware\DisableBladeIconComponents; use Filament\Http\Middleware\DispatchServingFilamentEvent;
use Filament\Panel; use Filament\PanelProvider; use Filament\Support\Assets\Css; use Filament\Support\Assets\Js; use Filament\Support\Colors\Color; use Filament\Support\Enums\Width;
use Illuminate\Cookie\Middleware\AddQueuedCookiesToResponse; use Illuminate\Cookie\Middleware\EncryptCookies; use Illuminate\Foundation\Http\Middleware\VerifyCsrfToken; use Illuminate\Routing\Middleware\SubstituteBindings; use Illuminate\Session\Middleware\StartSession; use Illuminate\Support\Facades\Vite; use Illuminate\View\Middleware\ShareErrorsFromSession;
class DemoPanelProvider extends PanelProvider
{ public function panel(Panel $panel): Panel { $baseDomain=parse_url(config('app.url'),PHP_URL_HOST) ?: config('app.url'); $demoDomain=env('DEMO_DOMAIN','demo.'.$baseDomain); return $panel->id('demo')->path('')->domain($demoDomain)->favicon(site_image(siteUrlSettings('site_favicon'),'images/skytech-infranet-logo.png'))->brandLogo(site_image(siteUrlSettings('site_logo'),'images/skytech-infranet-logo.png'))->brandName((siteUrlSettings('site_name') ?? 'SKYTECH INFRANET').' — Demo')->login(Login::class)->registration(null)->authGuard('web')->maxContentWidth(Width::Full)->colors(['primary'=>Color::hex(siteUrlSettings('theme_primary_color') ?? '#6366f1')])->pages([ChangePassword::class])->assets([Css::make('portal-custom-styles',Vite::asset('resources/css/app.css')),Js::make('portal-custom-js',Vite::asset('resources/js/app.js'))->module()])->middleware([EncryptCookies::class,AddQueuedCookiesToResponse::class,StartSession::class,AuthenticateSession::class,ShareErrorsFromSession::class,VerifyCsrfToken::class,SubstituteBindings::class,DisableBladeIconComponents::class,DispatchServingFilamentEvent::class])->authMiddleware([Authenticate::class,\App\Http\Middleware\EnsureDemoAccess::class]); } }
